const CATALOG={
 '71.001':{name:'White',hex:'#F1F1EB',range:'Vallejo Model Air'},'71.002':{name:'Medium Yellow',hex:'#F5B817',range:'Vallejo Model Air'},
 '71.003':{name:'Red RLM23',hex:'#C92B31',range:'Vallejo Model Air'},'71.004':{name:'Blue',hex:'#3156A6',range:'Vallejo Model Air'},
 '71.007':{name:'Olive Green',hex:'#5D6235',range:'Vallejo Model Air'},'71.057':{name:'Black',hex:'#1E2022',range:'Vallejo Model Air'},
 '71.063':{name:'Silver RLM01',hex:'#A8ADB0',range:'Vallejo Model Air'},'71.066':{name:'Gold',hex:'#B28B39',range:'Vallejo Model Air'},
 '70.951':{name:'White',hex:'#F2F1E8',range:'Vallejo Model Color'},'70.950':{name:'Black',hex:'#202124',range:'Vallejo Model Color'},
 '70. flat red':{name:'Flat Red',hex:'#B83232',range:'Vallejo Model Color'}
};
const starter=['71.001','71.002','71.003','71.004','71.007','71.057','71.063','71.066'].map(code=>({id:crypto.randomUUID(),code,...CATALOG[code]}));
const defaultPalettes=[{name:'Vallejo Model Air',use:'do aerografu'},{name:'Vallejo Model Color',use:'do pędzla'}];
const state={paints:load('mp-paints',starter),recipes:load('mp-recipes',[]),palettes:load('mp-palettes',defaultPalettes),target:'#7456D9',mix:[],lightness:86,palette:load('mp-palette','Vallejo Model Air')};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function load(k,f){try{const v=localStorage.getItem(k);return v===null?f:JSON.parse(v)}catch{return f}}function persist(){localStorage.setItem('mp-paints',JSON.stringify(state.paints));localStorage.setItem('mp-recipes',JSON.stringify(state.recipes));localStorage.setItem('mp-palettes',JSON.stringify(state.palettes));localStorage.setItem('mp-palette',JSON.stringify(state.palette))}
function hexRgb(h){h=h.replace('#','');if(h.length===3)h=[...h].map(x=>x+x).join('');return [0,2,4].map(i=>parseInt(h.slice(i,i+2),16))}function rgbHex(r){return '#'+r.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('').toUpperCase()}
function hsvRgb(h,s,v){let f=(n,k=(n+h/60)%6)=>v-v*s*Math.max(0,Math.min(k,4-k,1));return [f(5),f(3),f(1)].map(x=>x*255)}
function dist(a,b){return Math.sqrt(a.reduce((n,v,i)=>n+(v-b[i])**2,0))}function mixRgb(colors,weights){return [0,1,2].map(ch=>colors.reduce((n,c,i)=>n+Math.pow(c[ch]/255,1.45)*weights[i],0)**(1/1.45)*255)}
function calculateMix(){const paints=state.palette==='Wszystkie'?state.paints:state.paints.filter(p=>p.range===state.palette);if(!paints.length){state.mix=[];$('#accuracy').textContent='Brak farb';renderMix();return}const target=hexRgb(state.target);let best={d:1e9,items:[]};const top=[...paints].sort((a,b)=>dist(hexRgb(a.hex),target)-dist(hexRgb(b.hex),target)).slice(0,10);
  for(const p of top){const d=dist(hexRgb(p.hex),target);if(d<best.d)best={d,items:[{paint:p,w:1}]}}
  for(let i=0;i<top.length;i++)for(let j=i+1;j<top.length;j++)for(let a=1;a<20;a++){const w=a/20,r=mixRgb([hexRgb(top[i].hex),hexRgb(top[j].hex)],[w,1-w]),d=dist(r,target);if(d<best.d)best={d,items:[{paint:top[i],w},{paint:top[j],w:1-w}]}}
  const small=top.slice(0,7);for(let i=0;i<small.length;i++)for(let j=i+1;j<small.length;j++)for(let k=j+1;k<small.length;k++)for(let a=1;a<10;a++)for(let b=1;b<10-a;b++){const ws=[a/10,b/10,1-(a+b)/10],r=mixRgb([hexRgb(small[i].hex),hexRgb(small[j].hex),hexRgb(small[k].hex)],ws),d=dist(r,target)+5;if(d<best.d)best={d,items:[{paint:small[i],w:ws[0]},{paint:small[j],w:ws[1]},{paint:small[k],w:ws[2]}]}}
  state.mix=best.items.map(x=>({...x,drops:Math.max(1,Math.round(x.w*10))}));const gcd=(a,b)=>b?gcd(b,a%b):a;const g=state.mix.reduce((n,x)=>gcd(n,x.drops),state.mix[0]?.drops||1);state.mix.forEach(x=>x.drops/=g);$('#accuracy').textContent=`${Math.max(52,Math.round(100-best.d/4.3))}% zgodności`;renderMix()}
function dropWord(n){const last=n%10,lastTwo=n%100;return n===1?'kropla':last>=2&&last<=4&&(lastTwo<12||lastTwo>14)?'krople':'kropli'}
function renderMix(){const box=$('#mixResult'),graphic=$('#mixInfographic');if(!state.mix.length){graphic.innerHTML='';box.innerHTML=`<div class="empty-state"><strong>Brak farb w tej palecie</strong>Dodaj kolory do grupy „${esc(state.palette)}”, aby utworzyć mieszankę.</div>`;return}graphic.innerHTML=`<div class="mix-segments">${state.mix.map(({paint,drops})=>`<span class="mix-segment" style="background:${paint.hex};flex:${drops}">${drops}</span>`).join('')}</div><div class="mix-legend">${state.mix.map(({paint,drops})=>`<span class="mix-legend-item"><i class="mix-legend-dot" style="background:${paint.hex}"></i>${esc(paint.name)} · ${drops} ${dropWord(drops)}</span>`).join('')}</div>`;box.innerHTML=state.mix.map(({paint,drops})=>`<div class="mix-row"><span class="color-stripe" style="background:${paint.hex}"></span><span class="paint-dot" style="background:${paint.hex}"></span><div><div class="paint-title">${esc(paint.name)}</div><div class="paint-meta">${esc(paint.range)} · ${esc(paint.code)}</div></div><div class="parts"><strong>${drops}</strong><span>KROPLE</span></div></div>`).join('')}
function renderPaints(){const list=$('#paintList');$('#paintCount').textContent=state.paints.length;list.innerHTML=state.palettes.map(group=>{const paints=state.paints.filter(p=>p.range===group.name);return `<section class="palette-group"><div class="palette-group-head"><div><div class="palette-group-title">${esc(group.name)}</div><div class="palette-group-meta">${esc(group.use||'własna paleta')} · ${paints.length} kolorów</div></div><button class="add-to-palette" type="button" data-add-for="${esc(group.name)}">＋ Dodaj kolor</button></div>${paints.length?paints.map(p=>`<div class="paint-card"><span class="color-stripe" style="background:${p.hex}"></span><span class="paint-dot" style="background:${p.hex}"></span><div><div class="paint-title">${esc(p.name)}</div><div class="paint-meta">${esc(p.code)}</div></div><button class="delete-button" data-delete-paint="${p.id}">Usuń</button></div>`).join(''):'<div class="palette-group-empty">Ta grupa nie ma jeszcze kolorów.</div>'}</section>`}).join('')||'<div class="empty-state"><strong>Brak grup</strong>Najpierw dodaj grupę palety.</div>';calculateMix()}
function renderRecipes(){const list=$('#recipeList');list.innerHTML=state.recipes.length?state.recipes.map(r=>`<div class="recipe-card"><span class="color-stripe" style="background:${r.target}"></span><span class="recipe-swatch" style="background:${r.target}"></span><div><div class="paint-title">${esc(r.name)}</div><div class="paint-meta">${r.mix.map(x=>`${x.drops??x.parts} ${dropWord(x.drops??x.parts)} · ${esc(x.paint.name)}`).join(' · ')}</div><div class="recipe-date">${r.date}</div></div><button class="delete-button" data-delete-recipe="${r.id}">Usuń</button></div>`).join(''):'<div class="empty-state"><strong>Jeszcze pusto</strong>Zapisane mieszanki pojawią się tutaj.</div>'}
function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
const canvas=$('#colorWheel'),ctx=canvas.getContext('2d');function drawWheel(){const {width:w,height:h}=canvas,c=w/2,rad=w/2;ctx.clearRect(0,0,w,h);for(let a=0;a<360;a+=.6){ctx.beginPath();ctx.moveTo(c,c);ctx.arc(c,c,rad,(a-1)*Math.PI/180,(a+.8)*Math.PI/180);ctx.closePath();ctx.fillStyle=`hsl(${a} 88% 54%)`;ctx.fill()}const g=ctx.createRadialGradient(c,c,0,c,c,rad);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.08,'rgba(255,255,255,.94)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(c,c,rad,0,Math.PI*2);ctx.fill()}
function chooseAt(ev){ev.preventDefault();const rect=canvas.getBoundingClientRect(),x=(ev.clientX-rect.left)/rect.width*canvas.width,y=(ev.clientY-rect.top)/rect.height*canvas.height,c=canvas.width/2,dx=x-c,dy=y-c,r=Math.min(.97,Math.hypot(dx,dy)/c),h=(Math.atan2(dy,dx)*180/Math.PI+360)%360;state.target=rgbHex(hsvRgb(h,r,state.lightness/100));$('#wheelCursor').style.left=`${50+Math.cos(h*Math.PI/180)*r*50}%`;$('#wheelCursor').style.top=`${50+Math.sin(h*Math.PI/180)*r*50}%`;updateTarget()}
function updateTarget(){state.target=state.target.toUpperCase();$('#targetSwatch').style.background=state.target;$('#targetHex').textContent=state.target;$('#hexInput').value=state.target;calculateMix()}
const wheelSurface=$('.color-wheel-wrap');let wheelDragging=false;wheelSurface.addEventListener('pointerdown',e=>{wheelDragging=true;wheelSurface.setPointerCapture(e.pointerId);chooseAt(e)});wheelSurface.addEventListener('pointermove',e=>{if(wheelDragging)chooseAt(e)});wheelSurface.addEventListener('pointerup',e=>{wheelDragging=false;if(wheelSurface.hasPointerCapture(e.pointerId))wheelSurface.releasePointerCapture(e.pointerId)});wheelSurface.addEventListener('pointercancel',()=>wheelDragging=false);$('#toneRange').addEventListener('input',e=>{state.lightness=+e.target.value;const [r,g,b]=hexRgb(state.target),m=Math.max(r,g,b)||1;state.target=rgbHex([r,g,b].map(v=>v/m*255*state.lightness/100));updateTarget()});
$$('.nav-item').forEach(b=>b.onclick=()=>{$$('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.view').forEach(v=>v.classList.remove('active'));$('#'+b.dataset.view).classList.add('active');if(b.dataset.view==='recipesView')renderRecipes()});
function renderPalettes(){const choices=[{name:'Wszystkie',use:'wszystkie posiadane'},...state.palettes];$('#mixerPaletteSelect').innerHTML=choices.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join('');$('#mixerPaletteSelect').value=state.palette;$('#paintRange').innerHTML=state.palettes.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join('')}
function setPalette(palette){if(palette!=='Wszystkie'&&!state.palettes.some(p=>p.name===palette))palette=state.palettes[0]?.name||'Wszystkie';state.palette=palette;persist();renderPalettes();const info=state.palettes.find(p=>p.name===palette);$('#activePaletteLabel').textContent=palette==='Wszystkie'?'Wszystkie posiadane palety':palette+(info?.use?' · '+info.use:'');calculateMix()}
$('#mixerPaletteSelect').onchange=e=>setPalette(e.target.value);
$('#addPalette').onclick=()=>{$('#paletteForm').reset();$('#paletteDialog').showModal()};
$('#paletteForm').onsubmit=e=>{e.preventDefault();const name=$('#paletteName').value.trim(),use=$('#paletteUse').value.trim();if(!name)return;if(state.palettes.some(p=>p.name.toLowerCase()===name.toLowerCase())){toast('Taka paleta już istnieje');return}state.palettes.push({name,use:use||'własna paleta'});persist();setPalette(name);$('#paletteDialog').close();toast('Paleta dodana')};
document.addEventListener('click',e=>{const button=e.target.closest('.close-button');if(!button)return;e.preventDefault();e.stopPropagation();const dialog=button.closest('dialog');if(dialog?.open)dialog.close()},true);
$$('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()}));
function openPaintDialog(palette){if(!state.palettes.length){toast('Najpierw dodaj grupę palety');return}$('#paintForm').reset();renderPalettes();$('#paintRange').value=palette&&palette!=='Wszystkie'?palette:(state.palettes[0]?.name||'');$('#paintColor').value='#3156a6';$('#paintHex').value='#3156A6';$('#paintSuggestion').classList.add('hidden');$('#paintDialog').showModal()}
$('#addPaint').onclick=()=>openPaintDialog(state.palette);
$('#paintCode').addEventListener('input',e=>{const key=e.target.value.trim(),p=CATALOG[key];if(p){$('#paintName').value=p.name;$('#paintRange').value=p.range;$('#paintColor').value=p.hex;$('#paintHex').value=p.hex;$('#paintSuggestion').textContent=`Rozpoznano: ${p.range} — ${p.name}`;$('#paintSuggestion').classList.remove('hidden')}else $('#paintSuggestion').classList.add('hidden')});
$('#paintColor').oninput=e=>$('#paintHex').value=e.target.value.toUpperCase();$('#paintHex').oninput=e=>{if(/^#[0-9a-f]{6}$/i.test(e.target.value))$('#paintColor').value=e.target.value};
$('#paintForm').onsubmit=e=>{e.preventDefault();const hex=$('#paintHex').value;if(!/^#[0-9a-f]{6}$/i.test(hex)){toast('Sprawdź kod HEX');return}state.paints.push({id:crypto.randomUUID(),range:$('#paintRange').value,code:$('#paintCode').value.trim(),name:$('#paintName').value.trim(),hex:hex.toUpperCase()});persist();renderPaints();$('#paintDialog').close();toast('Farba dodana')};
$('#paintList').onclick=e=>{const add=e.target.closest('[data-add-for]');if(add){openPaintDialog(add.dataset.addFor);return}const id=e.target.dataset.deletePaint;if(id){state.paints=state.paints.filter(p=>p.id!==id);persist();renderPaints();toast('Farba usunięta')}};$('#recipeList').onclick=e=>{const id=e.target.dataset.deleteRecipe;if(id){state.recipes=state.recipes.filter(r=>r.id!==id);persist();renderRecipes();toast('Receptura usunięta')}};
$('#saveRecipe').onclick=()=>{if(!state.mix.length){toast('Najpierw dodaj farby');return}$('#recipeName').value='';$('#recipePreview').innerHTML=`<div class="paint-title" style="color:${state.target}">${state.target}</div><div class="paint-meta">${state.mix.map(x=>`${x.drops} ${dropWord(x.drops)} · ${esc(x.paint.name)}`).join(' · ')}</div>`;$('#recipeDialog').showModal()};
$('#recipeForm').onsubmit=e=>{e.preventDefault();state.recipes.unshift({id:crypto.randomUUID(),name:$('#recipeName').value.trim(),target:state.target,mix:state.mix,date:new Intl.DateTimeFormat('pl-PL',{day:'numeric',month:'long',year:'numeric'}).format(new Date())});persist();renderRecipes();$('#recipeDialog').close();toast('Receptura zapisana')};
$('#adjustMix').onclick=()=>{if(!state.mix.length)return;$('#adjustRows').innerHTML=state.mix.map((x,i)=>`<label class="adjust-line"><span style="background:${x.paint.hex}"></span><span>${esc(x.paint.name)}</span><input type="number" min="1" max="30" value="${x.drops}" data-adjust="${i}" aria-label="Krople ${esc(x.paint.name)}"></label>`).join('');$('#adjustDialog').showModal()};
$('#adjustForm').onsubmit=e=>{e.preventDefault();$$('[data-adjust]').forEach(i=>state.mix[+i.dataset.adjust].drops=Math.max(1,+i.value||1));renderMix();$('#adjustDialog').close();toast('Liczba kropli poprawiona')};
$('#openHex').onclick=()=>$('#hexDialog').showModal();$('#hexForm').onsubmit=e=>{e.preventDefault();const h=$('#hexInput').value;if(!/^#[0-9a-f]{6}$/i.test(h)){toast('Wpisz pełny kod HEX');return}state.target=h;updateTarget();$('#hexDialog').close()};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installButton').classList.remove('hidden')});$('#installButton').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installButton').classList.add('hidden')}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));
drawWheel();setPalette(state.palette);renderPaints();renderRecipes();updateTarget();
